// @FIGURE_CODE_BEGIN
// ---- element spec ----
// double cone (2 nappes) -> LatheGeometry, MeshBasicMaterial pale blue #CFE0F5, 0.55, DoubleSide, depthWrite false
// upper rim            -> Line (circle y=+2, r=1.05) solid #1F4E9C
// lower rim            -> Line (circle y=-2, r=1.05) dashed LineDashedMaterial #1F4E9C
// silhouette X edges   -> 2 Lines through apex, #1F4E9C
// cutting plane        -> PlaneGeometry 3.2x3.2, MeshBasicMaterial #AFC6E4 0.25 + border Line
// conic curve          -> up to 2 Lines, red #E23A2E, analytic intersection
// arrowheads           -> ConeGeometry(0.07,0.2) red, on open ends
// labels               -> addLabel: column title above, curve name below

const BLUE = 0x1F4E9C, FILL = 0xCFE0F5, RED = 0xE23A2E, PLANEC = 0xAFC6E4;
const K = 0.525;              // r = K*|y|
const YMAX = 2.0, RRIM = K * YMAX;
const SLANT = Math.atan(1 / K) * 180 / Math.PI;   // 62.3 deg

// ---------- cone group ----------
const coneGroup = new THREE.Group();
scene.add(coneGroup);

function nappe(sign) {
  // lathe profile from apex (0,0) to rim
  const pts = [];
  const N = 24;
  for (let i = 0; i <= N; i++) {
    const y = sign * YMAX * (i / N);
    pts.push(new THREE.Vector2(Math.abs(K * y), y));
  }
  const g = new THREE.LatheGeometry(pts, 64);
  const m = new THREE.MeshBasicMaterial({
    color: FILL, transparent: true, opacity: 0.55,
    side: THREE.DoubleSide, depthWrite: false
  });
  return new THREE.Mesh(g, m);
}
const nappeUp = nappe(1), nappeDn = nappe(-1);
coneGroup.add(nappeUp, nappeDn);

function circlePts(y, r, n = 96) {
  const p = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n * Math.PI * 2;
    p.push(new THREE.Vector3(r * Math.cos(t), y, r * Math.sin(t)));
  }
  return p;
}
const rimTop = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(circlePts(YMAX, RRIM)),
  new THREE.LineBasicMaterial({ color: BLUE })
);
const rimBotGeo = new THREE.BufferGeometry().setFromPoints(circlePts(-YMAX, RRIM));
const rimBot = new THREE.Line(rimBotGeo, new THREE.LineDashedMaterial({ color: BLUE, dashSize: 0.12, gapSize: 0.08 }));
rimBot.computeLineDistances();
coneGroup.add(rimTop, rimBot);

// silhouette X edges (in the plane z=0 as drawn front-on)
for (const s of [1, -1]) {
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(s * RRIM, YMAX, 0),
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(-s * RRIM, -YMAX, 0)
  ]);
  coneGroup.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: BLUE })));
}

// ---------- cutting plane ----------
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(3.2, 3.2),
  new THREE.MeshBasicMaterial({ color: PLANEC, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false })
);
const planeEdge = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.6, -1.6, 0), new THREE.Vector3(1.6, -1.6, 0),
    new THREE.Vector3(1.6, 1.6, 0), new THREE.Vector3(-1.6, 1.6, 0)
  ]),
  new THREE.LineBasicMaterial({ color: 0x7f9dc4 })
);
const planeGroup = new THREE.Group();
planeGroup.add(planeMesh, planeEdge);
scene.add(planeGroup);

// ---------- red curve container ----------
const curveGroup = new THREE.Group();
scene.add(curveGroup);
const redMat = () => new THREE.LineBasicMaterial({ color: RED, linewidth: 2 });

function clearCurves() {
  while (curveGroup.children.length) {
    const o = curveGroup.children.pop();
    o.geometry?.dispose?.(); o.material?.dispose?.();
  }
}

function addPolyline(pts) {
  if (pts.length < 2) return null;
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), redMat());
  curveGroup.add(l);
  return l;
}

function addArrow(tip, dir) {
  const m = new THREE.Mesh(
    new THREE.ConeGeometry(0.065, 0.19, 12),
    new THREE.MeshBasicMaterial({ color: RED })
  );
  m.position.copy(tip);
  const d = dir.clone().normalize();
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
  curveGroup.add(m);
}

// ---------- plane geometry math ----------
// plane origin P0, basis u (screen-horizontal X), v (tilted in Y/Z)
// tilt theta from horizontal, rotation about X axis.
function planeFrame(tiltDeg, offsetY, offsetZ) {
  const th = THREE.MathUtils.degToRad(tiltDeg);
  const P0 = new THREE.Vector3(0, offsetY, offsetZ);
  const u = new THREE.Vector3(1, 0, 0);
  const v = new THREE.Vector3(0, Math.sin(th), Math.cos(th));
  const n = new THREE.Vector3().crossVectors(u, v).normalize();
  return { P0, u, v, n, th };
}

// Point on plane: P = P0 + a*u + b*v
// Cone: x^2 + z^2 - K^2 y^2 = 0
// Substituting gives a quadratic in a for each b -> solve.
function conicPoints(fr, bRange, steps) {
  const { P0, u, v } = fr;
  const out = [[], []];       // two sheets (a+ and a-)
  const K2 = K * K;
  for (let i = 0; i <= steps; i++) {
    const b = bRange[0] + (bRange[1] - bRange[0]) * i / steps;
    const px = P0.x + b * v.x, py = P0.y + b * v.y, pz = P0.z + b * v.z;
    // x = px + a, y = py, z = pz  (u = X axis)
    // (px+a)^2 + pz^2 - K2*py^2 = 0
    const C = px * px + pz * pz - K2 * py * py;
    const B = 2 * px;
    const disc = B * B - 4 * C;
    if (disc < 0) { out[0].push(null); out[1].push(null); continue; }
    const s = Math.sqrt(disc);
    const a1 = (-B + s) / 2, a2 = (-B - s) / 2;
    const mk = (a) => {
      const p = new THREE.Vector3(px + a, py, pz);
      if (Math.abs(p.y) > YMAX + 1e-9) return null;
      return p;
    };
    out[0].push(mk(a1));
    out[1].push(mk(a2));
  }
  return out;
}

function splitRuns(arr) {
  const runs = []; let cur = [];
  for (const p of arr) {
    if (p) cur.push(p);
    else { if (cur.length > 1) runs.push(cur); cur = []; }
  }
  if (cur.length > 1) runs.push(cur);
  return runs;
}

function classify(tilt) {
  if (tilt < 0.5) return 'Circle';
  if (Math.abs(tilt - SLANT) < 1.2) return 'Parabola';
  if (tilt < SLANT) return 'Ellipse';
  return 'Hyperbola';
}

// ---------- state ----------
const state = { step: 0, tilt: 30, mode: 'cone', showPlane: true };
// per-column plane placement: [offsetY, offsetZ]
const PLACE = [[0.9, 0], [0.9, 0], [0, 0.6], [0, 0.6]];

let curveWorld = [];   // arrays of points for "curve alone" framing

function rebuild() {
  const place = PLACE[state.step];
  const fr = planeFrame(state.tilt, place[0], place[1]);

  // orient plane mesh
  planeGroup.position.copy(fr.P0);
  const m = new THREE.Matrix4().makeBasis(fr.u, fr.v, fr.n);
  planeGroup.quaternion.setFromRotationMatrix(m);
  planeGroup.visible = state.showPlane && state.mode === 'cone';

  clearCurves();
  curveWorld = [];
  const type = classify(state.tilt);
  const runsAll = [];
  const [sA, sB] = conicPoints(fr, [-3.0, 3.0], 900);
  for (const sheet of [sA, sB]) for (const r of splitRuns(sheet)) runsAll.push(r);

  // Merge the two sheets into closed loop for bounded cases
  if (type === 'Ellipse' || type === 'Circle') {
    const a = splitRuns(sA)[0], b = splitRuns(sB)[0];
    if (a && b) {
      const loop = a.concat(b.slice().reverse());
      loop.push(loop[0].clone());
      addPolyline(loop);
      curveWorld.push(loop);
    }
  } else {
    for (const r of runsAll) {
      if (r.length < 3) continue;
      addPolyline(r);
      curveWorld.push(r);
      // arrowheads at open ends that reach the rim planes
      const ends = [[r[0], r[1]], [r[r.length - 1], r[r.length - 2]]];
      for (const [tip, prev] of ends) {
        if (Math.abs(Math.abs(tip.y) - YMAX) < 0.12) {
          addArrow(tip, tip.clone().sub(prev));
        }
      }
    }
  }

  // visibility / fade for curve-alone mode
  const showCone = state.mode === 'cone';
  nappeUp.material.opacity = showCone ? 0.55 : 0.0;
  nappeDn.material.opacity = showCone ? 0.55 : 0.0;
  coneGroup.children.forEach(o => { if (o.isLine) o.visible = showCone; });
  nappeUp.visible = showCone; nappeDn.visible = showCone;

  document.getElementById('classify').textContent =
    `tilt ${state.tilt}° → ${type}` + (state.tilt < SLANT && state.tilt > 0.5 ? ' (closed, one nappe)' :
      type === 'Hyperbola' ? ' (both nappes)' : type === 'Parabola' ? ' (parallel to slant line)' : '');
}

// camera helper: for "curve alone" look straight down the plane normal
function applyView() {
  if (state.mode === 'cone') {
    setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.7 });
  } else {
    const place = PLACE[state.step];
    const fr = planeFrame(state.tilt, place[0], place[1]);
    // normal direction -> azimuth/elevation
    const n = fr.n.clone();
    if (n.z < 0) n.negate();
    const elevationDeg = THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(n.y, -1, 1)));
    const azimuthDeg = THREE.MathUtils.radToDeg(Math.atan2(n.z, n.x));
    setCameraView({ projection: 'orthographic', azimuthDeg, elevationDeg, heightFraction: 0.65 });
  }
}

// ---------- labels ----------
const TITLES = ['Diagonal Slice', 'Horizontal Slice', 'Deep Vertical Slice', 'Vertical Slice'];
const NAMES = ['Ellipse', 'Circle', 'Hyperbola', 'Parabola'];
const titleLbl = addLabel(TITLES[0], new THREE.Vector3(0, YMAX + 0.55, 0), { bold: true, fontSize: '15px' });
const nameLbl = addLabel(NAMES[0], new THREE.Vector3(0, -YMAX - 0.55, 0), { bold: true, fontSize: '15px', color: '#B02318' });
addLabel('apex', new THREE.Vector3(0, 0, 0), { fontSize: '11px', color: '#1F4E9C', offset: [34, 0] });

function syncLabels() {
  titleLbl.div.innerHTML = TITLES[state.step];
  const t = classify(state.tilt);
  nameLbl.div.innerHTML = t;
  nameLbl.div.style.display = '';
}

// ---------- interactivity ----------
registerInteractive(nappeUp, {
  title: 'Upper nappe',
  tooltip: 'Upper nappe of the double cone',
  body: 'The cone is x² + z² = (0.525y)², two nappes meeting at the apex. A plane that meets only this nappe gives an ellipse, circle or parabola.'
});
registerInteractive(nappeDn, {
  title: 'Lower nappe',
  tooltip: 'Lower nappe of the double cone',
  body: 'When the cutting plane is steeper than the 62.3° slant angle it reaches this nappe too, and the intersection breaks into the two branches of a hyperbola.'
});
registerInteractive(planeMesh, {
  title: 'Cutting plane',
  tooltip: 'The cutting plane — drag the tilt slider',
  body: 'The plane is tilted by θ about the screen-horizontal axis. θ = 0 gives a circle, 0 < θ < 62.3° an ellipse, θ = 62.3° a parabola, θ > 62.3° a hyperbola.'
});

// ---------- UI wiring ----------
const elTilt = document.getElementById('planeTilt');
const elTiltVal = document.getElementById('tiltVal');
const elStep = document.getElementById('conicStep');
const btnCone = document.getElementById('modeCone');
const btnCurve = document.getElementById('modeCurve');
const elShowPlane = document.getElementById('showPlane');

function refresh(recamera) {
  elTilt.value = state.tilt;
  elTiltVal.textContent = state.tilt;
  elStep.value = String(state.step);
  btnCone.classList.toggle('active', state.mode === 'cone');
  btnCurve.classList.toggle('active', state.mode === 'curve');
  elShowPlane.checked = state.showPlane;
  rebuild();
  syncLabels();
  if (recamera) applyView();
}

elTilt.addEventListener('input', () => {
  state.tilt = +elTilt.value;
  refresh(state.mode === 'curve');
});
elStep.addEventListener('change', () => {
  state.step = +elStep.value;
  state.tilt = [30, 0, 85, 62][state.step];
  refresh(true);
});
btnCone.addEventListener('click', () => { state.mode = 'cone'; refresh(true); });
btnCurve.addEventListener('click', () => { state.mode = 'curve'; refresh(true); });
elShowPlane.addEventListener('change', () => { state.showPlane = elShowPlane.checked; rebuild(); });

// ---------- demo steps ----------
const STEPS = [
  { title: 'Diagonal Slice → Ellipse', narration: 'A plane tilted about 30° from horizontal cuts clean through one nappe; the red intersection closes up into a tilted ellipse.', s: { step: 0, tilt: 30, mode: 'cone' } },
  { title: 'The ellipse alone', narration: 'Lift the curve off the cone: viewed inside its own plane it is the flattened oval labelled Ellipse.', s: { step: 0, tilt: 30, mode: 'curve' } },
  { title: 'Horizontal Slice → Circle', narration: "Flatten the plane to 0°, perpendicular to the cone's axis, and the ellipse tightens into a perfect circle.", s: { step: 1, tilt: 0, mode: 'cone' } },
  { title: 'Vertical Slice → Parabola', narration: 'Tilt to about 62°, exactly parallel to a slant line of the cone. The curve can no longer close; it escapes as a parabola.', s: { step: 3, tilt: 62, mode: 'cone' } },
  { title: 'Deep Vertical Slice → Hyperbola', narration: 'Past the slant angle, at 85°, the plane strikes both nappes at once, producing two opposing red branches.', s: { step: 2, tilt: 85, mode: 'cone' } },
  { title: 'Both branches alone', narration: 'Isolated in its plane, the same intersection is the familiar two-branch hyperbola graph.', s: { step: 2, tilt: 85, mode: 'curve' } }
];
let stepIdx = 0, playing = false, playTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  const from = state.tilt;
  state.step = st.s.step; state.mode = st.s.mode;
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('stepNarr').textContent = st.narration;
  // tween the tilt
  const to = st.s.tilt, t0 = performance.now(), dur = 700;
  function tween() {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    state.tilt = Math.round(from + (to - from) * e);
    refresh(k === 1);
    if (k < 1) requestAnimationFrame(tween);
  }
  tween();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnPlay').addEventListener('click', function () {
  playing = !playing;
  this.textContent = playing ? '❚❚ Pause' : '▶ Demo';
  clearInterval(playTimer);
  if (playing) playTimer = setInterval(() => goToStep(stepIdx + 1), 3200);
});

// ---------- init ----------
refresh(false);
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.7 });
document.getElementById('stepTitle').textContent = STEPS[0].title;
document.getElementById('stepNarr').textContent = STEPS[0].narration;
