// @FIGURE_CODE_BEGIN
// ---- element spec ----
// double cone (2 nappes) -> LatheGeometry, MeshBasicMaterial #CFE0F5 0.55 DoubleSide depthWrite:false
// upper rim              -> Line circle y=+2 r=1.05 solid #1F4E9C
// lower rim              -> Line circle y=-2 r=1.05 LineDashedMaterial #1F4E9C
// silhouette X edges     -> 2 Lines (3 pts: rim -> apex -> opposite rim), angles recomputed per frame from camera
// cutting plane          -> PlaneGeometry(1,1) scaled to cone footprint, #AFC6E4 0.25 + LineLoop border
// conic curve            -> TubeGeometry tubes radius .03, MeshBasicMaterial #E23A2E, depthTest false
// arrowheads             -> ConeGeometry(0.08,0.22) red on open ends
// labels                 -> addLabel: column title above, curve name below / above isolated curve, apex tag

const BLUE = 0x1F4E9C, FILL = 0xCFE0F5, RED = 0xE23A2E, PLANEC = 0xAFC6E4;
const K = 0.525;
const YMAX = 2.0, RRIM = K * YMAX;
const SLANT = Math.atan(1 / K) * 180 / Math.PI;   // 62.3 deg

// ---------- cone group ----------
const coneGroup = new THREE.Group();
scene.add(coneGroup);
let coneInScene = true;

function nappe(sign) {
  const pts = [];
  const N = 20;
  for (let i = 0; i <= N; i++) {
    const y = sign * YMAX * (i / N);
    pts.push(new THREE.Vector2(Math.abs(K * y), y));
  }
  const g = new THREE.LatheGeometry(pts, 72);
  const m = new THREE.MeshBasicMaterial({
    color: FILL, transparent: true, opacity: 0.55,
    side: THREE.DoubleSide, depthWrite: false
  });
  return new THREE.Mesh(g, m);
}
const nappeUp = nappe(1), nappeDn = nappe(-1);
coneGroup.add(nappeUp, nappeDn);

function circlePts(y, r, n = 120) {
  const p = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n * Math.PI * 2;
    p.push(new THREE.Vector3(r * Math.cos(t), y, r * Math.sin(t)));
  }
  return p;
}
const rimTop = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(circlePts(YMAX, RRIM)),
  new THREE.LineBasicMaterial({ color: BLUE })
);
const rimBot = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(circlePts(-YMAX, RRIM)),
  new THREE.LineDashedMaterial({ color: BLUE, dashSize: 0.13, gapSize: 0.09 })
);
rimBot.computeLineDistances();
coneGroup.add(rimTop, rimBot);

// ---- view-dependent silhouette edges ----
const silLines = [];
for (let i = 0; i < 2; i++) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(9), 3));
  const L = new THREE.Line(g, new THREE.LineBasicMaterial({ color: BLUE }));
  L.frustumCulled = false;
  silLines.push(L);
  coneGroup.add(L);
}

// Cone: x^2+z^2 = K^2 y^2.  Normal at generator angle phi (upper) ~ (cos,-K,sin).
// Silhouette: n . v = 0  with v the projection direction  ->  A cos(phi-psi) = K*vy.
function updateSilhouette() {
  const v = camera.position.clone().sub(controls.target).normalize();
  const A = Math.hypot(v.x, v.z);
  let phis = null;
  if (A > 1e-6) {
    const c = K * v.y / A;
    if (Math.abs(c) <= 1) {
      const psi = Math.atan2(v.z, v.x), al = Math.acos(c);
      phis = [psi + al, psi - al];
    }
  }
  for (let i = 0; i < 2; i++) {
    const L = silLines[i];
    if (!phis) { L.visible = false; continue; }
    L.visible = true;
    const ph = phis[i];
    const x = RRIM * Math.cos(ph), z = RRIM * Math.sin(ph);
    const p = L.geometry.attributes.position;
    p.setXYZ(0, x, YMAX, z);
    p.setXYZ(1, 0, 0, 0);
    p.setXYZ(2, -x, -YMAX, -z);
    p.needsUpdate = true;
    L.geometry.computeBoundingSphere();
  }
}
updateSilhouette();
(function silLoop() { requestAnimationFrame(silLoop); if (coneInScene) updateSilhouette(); })();

// ---------- cutting plane ----------
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(1, 1),
  new THREE.MeshBasicMaterial({ color: PLANEC, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false })
);
const planeEdge = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.5, -0.5, 0), new THREE.Vector3(0.5, -0.5, 0),
    new THREE.Vector3(0.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)
  ]),
  new THREE.LineBasicMaterial({ color: 0x7f9dc4 })
);
const planeGroup = new THREE.Group();
planeGroup.add(planeMesh, planeEdge);
let planeInScene = false;

// ---------- red curve container ----------
const curveGroup = new THREE.Group();
scene.add(curveGroup);

function clearCurves() {
  while (curveGroup.children.length) {
    const o = curveGroup.children.pop();
    o.geometry?.dispose?.(); o.material?.dispose?.();
  }
}
function redMat() {
  return new THREE.MeshBasicMaterial({ color: RED, depthTest: false, depthWrite: false });
}
function addTube(ptsIn, closed) {
  const pts = [];
  for (const p of ptsIn) {
    if (!pts.length || p.distanceTo(pts[pts.length - 1]) > 1e-4) pts.push(p.clone());
  }
  if (closed && pts.length > 2 && pts[0].distanceTo(pts[pts.length - 1]) < 1e-3) pts.pop();
  if (pts.length < 3) return;
  const curve = new THREE.CatmullRomCurve3(pts, !!closed, 'centripetal');
  const seg = Math.min(420, Math.max(40, pts.length * 2));
  const g = new THREE.TubeGeometry(curve, seg, 0.03, 10, !!closed);
  const m = new THREE.Mesh(g, redMat());
  m.renderOrder = 10;
  curveGroup.add(m);
}
function addArrow(tip, dir) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.22, 14), redMat());
  m.renderOrder = 11;
  m.position.copy(tip);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  curveGroup.add(m);
}

// ---------- plane math ----------
function planeFrame(tiltDeg, offsetY, offsetZ) {
  const th = THREE.MathUtils.degToRad(tiltDeg);
  const P0 = new THREE.Vector3(0, offsetY, offsetZ);
  const u = new THREE.Vector3(1, 0, 0);
  const v = new THREE.Vector3(0, Math.sin(th), Math.cos(th));
  const n = new THREE.Vector3().crossVectors(u, v).normalize();
  return { P0, u, v, n, th };
}
// P = P0 + a*u + b*v ; substitute into x^2+z^2-K^2 y^2 = 0, solve quadratic in a.
function conicPoints(fr, bRange, steps) {
  const { P0, v } = fr;
  const out = [[], []];
  const K2 = K * K;
  for (let i = 0; i <= steps; i++) {
    const b = bRange[0] + (bRange[1] - bRange[0]) * i / steps;
    const px = P0.x + b * v.x, py = P0.y + b * v.y, pz = P0.z + b * v.z;
    const C = px * px + pz * pz - K2 * py * py;
    const B = 2 * px;
    const disc = B * B - 4 * C;
    if (disc < 0) { out[0].push(null); out[1].push(null); continue; }
    const s = Math.sqrt(disc);
    const mk = (a) => {
      const p = new THREE.Vector3(px + a, py, pz);
      return Math.abs(p.y) > YMAX + 1e-9 ? null : p;
    };
    out[0].push(mk((-B + s) / 2));
    out[1].push(mk((-B - s) / 2));
  }
  return out;
}
function splitRuns(arr) {
  const runs = []; let cur = [];
  for (const p of arr) {
    if (p) cur.push(p);
    else { if (cur.length > 1) runs.push(cur); cur = []; }
  }
  if (cur.length > 1) runs.push(cur);
  return runs;
}
function classify(tilt) {
  if (tilt < 0.5) return 'Circle';
  if (Math.abs(tilt - SLANT) < 1.2) return 'Parabola';
  if (tilt < SLANT) return 'Ellipse';
  return 'Hyperbola';
}

// ---------- state ----------
const state = { step: 0, tilt: 30, mode: 'cone', showPlane: true };
const PLACE = [[0.9, 0], [0.9, 0], [0, 0.6], [0, 0.6]];

function rebuild() {
  const place = PLACE[state.step];
  const fr = planeFrame(state.tilt, place[0], place[1]);

  // plane sized to the cone's footprint: 2.5 wide, tall only when steep
  planeGroup.position.copy(fr.P0);
  planeGroup.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(fr.u, fr.v, fr.n));
  planeGroup.scale.set(2.5, 2.3 + 1.6 * Math.abs(Math.sin(fr.th)), 1);
  const wantPlane = state.showPlane && state.mode === 'cone';
  if (wantPlane && !planeInScene) { scene.add(planeGroup); planeInScene = true; }
  else if (!wantPlane && planeInScene) { scene.remove(planeGroup); planeInScene = false; }

  clearCurves();
  const type = classify(state.tilt);
  const [sA, sB] = conicPoints(fr, [-3.2, 3.2], 1100);

  if (type === 'Ellipse' || type === 'Circle') {
    const a = splitRuns(sA)[0], b = splitRuns(sB)[0];
    if (a && b) addTube(a.concat(b.slice().reverse()), true);
  } else {
    const runs = [];
    for (const sheet of [sA, sB]) for (const r of splitRuns(sheet)) runs.push(r);
    for (const r of runs) {
      if (r.length < 4) continue;
      addTube(r, false);
      const ends = [[r[0], r[1]], [r[r.length - 1], r[r.length - 2]]];
      for (const [tip, prev] of ends) {
        if (Math.abs(Math.abs(tip.y) - YMAX) < 0.14) addArrow(tip, tip.clone().sub(prev));
      }
    }
  }

  const showCone = state.mode === 'cone';
  if (showCone && !coneInScene) { scene.add(coneGroup); coneInScene = true; updateSilhouette(); }
  else if (!showCone && coneInScene) { scene.remove(coneGroup); coneInScene = false; }

  document.getElementById('classify').textContent =
    `tilt ${state.tilt}° → ${type}` + (state.tilt < SLANT && state.tilt > 0.5 ? ' (closed, one nappe)' :
      type === 'Hyperbola' ? ' (both nappes)' : type === 'Parabola' ? ' (parallel to slant line)' : '');
}

// ---------- camera ----------
function applyView() {
  if (state.mode === 'cone') {
    // front-on orthographic, slight elevation → the familiar hourglass with elliptical rims
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 13, heightFraction: 0.72 });
  } else {
    const place = PLACE[state.step];
    const fr = planeFrame(state.tilt, place[0], place[1]);
    const n = fr.n.clone();
    if (n.y > 0) n.negate();
    const elev = THREE.MathUtils.clamp(THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(n.y, -1, 1))), -88, 88);
    const horiz = Math.hypot(n.x, n.z);
    const az = horiz < 1e-6 ? 90 : THREE.MathUtils.radToDeg(Math.atan2(n.z, n.x));
    setCameraView({ projection: 'orthographic', azimuthDeg: az, elevationDeg: elev, heightFraction: 0.6 });
  }
}

// ---------- labels ----------
const TITLES = ['Diagonal Slice', 'Horizontal Slice', 'Deep Vertical Slice', 'Vertical Slice'];
const titleLbl = addLabel(TITLES[0], new THREE.Vector3(0, YMAX + 0.62, 0), { bold: true, fontSize: '15px' });
const nameLbl = addLabel('Ellipse', new THREE.Vector3(0, -YMAX - 0.85, 0), { bold: true, fontSize: '15px' });
const apexLbl = addLabel('apex', new THREE.Vector3(0, 0, 0), { fontSize: '11px', color: '#1F4E9C', offset: [30, -8] });

function placeLabels() {
  const t = classify(state.tilt);
  nameLbl.div.innerHTML = t;
  titleLbl.div.innerHTML = TITLES[state.step];
  if (state.mode === 'cone') {
    titleLbl.div.style.display = '';
    apexLbl.div.style.display = '';
    titleLbl.pos.set(0, YMAX + 0.62, 0); titleLbl.offset = [0, 0];
    nameLbl.pos.set(0, -YMAX - 0.85, 0); nameLbl.offset = [0, 16];
  } else {
    titleLbl.div.style.display = 'none';
    apexLbl.div.style.display = 'none';
    scene.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(curveGroup);
    const c = new THREE.Vector3(); box.getCenter(c);
    const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion).normalize();
    let ext = 0;
    for (let i = 0; i < 8; i++) {
      const p = new THREE.Vector3(
        (i & 1) ? box.max.x : box.min.x,
        (i & 2) ? box.max.y : box.min.y,
        (i & 4) ? box.max.z : box.min.z).sub(c);
      ext = Math.max(ext, p.dot(up));
    }
    nameLbl.pos.copy(c).addScaledVector(up, ext + 0.4);
    nameLbl.offset = [0, -6];
  }
}

// ---------- interactivity hooks ----------
registerInteractive(nappeUp, {
  title: 'Upper nappe',
  tooltip: 'Upper nappe of the double cone',
