        const byId = document.getElementById(slotId);
        if (byId) return byId;
        const namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      const existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      const span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
