      phis = [psi + al, psi - al];
    }
  }
  for (let i = 0; i < 2; i++) {
    const L = silLines[i];
    if (!phis) { L.visible = false; continue; }
    L.visible = true;
    const ph = phis[i];
    const x = RRIM * Math.cos(ph), z = RRIM * Math.sin(ph);
    const p = L.geometry.attributes.position;
    p.setXYZ(0, x, YMAX, z);
    p.setXYZ(1, 0, 0, 0);
